# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, JSON, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerSubPrediction(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_sub_prediction"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    route_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_route.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "FK to explorer_agg_route with CASCADE delete. The route for "
            "which this completion time prediction was generated."
        ),
    )
    predicted_s: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Predicted total time to complete the route in seconds, including "
            "estimated stops."
        ),
    )
    predicted_moving_s: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Predicted moving-only time in seconds, excluding anticipated "
            "rest stops."
        ),
    )
    model_version: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Integer version number of the ML prediction model used to "
            "generate this estimate."
        ),
    )
    inputs: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB snapshot of the input parameters (user fitness, pace "
            "curve, weather, etc.) fed into the prediction model."
        ),
    )
    track_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("explorer_agg_track.id", ondelete="SET NULL"),
        description=(
            "FK to explorer_agg_track with SET NULL on delete. Optional link "
            "to a recorded track used to calibrate or validate this "
            "prediction."
        ),
    )
